<script setup lang="ts">
import { computed, ref } from 'vue'
import { app, start, toast, useInks, SHELF, type Box } from '../session'
import { SETTINGS, type Settings } from '../rules/state'
import { PROVIDERS } from '../dm/llm'
import { mine, choose } from '../heroes'
import { sheet } from '../rules/hero'
import { rich } from './rich'
import Cover from './Cover.vue'
import Portrait from './Portrait.vue'
import LlmForm from './LlmForm.vue'
import Bar from './Bar.vue'
const mode = ref<'ai' | 'dm'>(app.modalArg === 'dm' ? 'dm' : 'ai'); app.modalArg = null; const pick = ref<Box | null>(SHELF.find(b => b.id === app.box) ?? null), busy = ref(false), more = ref(false)
const band = ref('all'); const BANDS = [['all', 'All levels'], ['low', 'From level 1'], ['mid', 'From level 3'], ['high', 'From level 7']]; const shown = computed(() => SHELF.filter(b => band.value === 'all' || (band.value === 'low' ? b.lo <= 2 : band.value === 'mid' ? b.lo >= 3 && b.lo <= 6 : b.lo >= 7)))
if (pick.value) useInks(pick.value.inks); const take = (b: Box) => { pick.value = b; app.box = b.id; useInks(b.inks) }; const back = () => { if (pick.value) { pick.value = null; app.box = ''; useInks() } else app.screen = 'title' }
const set = ref<Settings>({ ...SETTINGS }); const hero = computed(() => mine.list.find(h => h.id === mine.chosen) ?? null); const D: [Settings['difficulty'], string][] = [['story', 'Story'], ['easy', 'Easy'], ['normal', 'Normal'], ['hard', 'Hard'], ['deadly', 'Deadly']]; const llm = computed(() => PROVIDERS.find(p => p.id === app.llm.provider)!)
const go = async () => { if (busy.value || !pick.value) return; if (mode.value === 'ai' && !hero.value) { toast('Choose or make a hero first.', true); return } if (mode.value === 'ai' && hero.value!.dead) { toast('That hero has fallen. Choose another.', true); return } busy.value = true; await start({ module: pick.value.id, mode: mode.value, set: { ...set.value }, hero: hero.value?.id }); busy.value = false }
const newHero = () => { app.modalArg = 'shelf'; app.screen = 'heroes' }
const KIND: Record<string, string> = { village: 'town', castle: 'hall or castle', dungeon: 'underground', cave: 'caves', wilds: 'open country', tower: 'tower', realm: 'whole country' }
const num = (n: number) => n.toLocaleString('en')
</script>
<template><main class="sh paper"><Bar :title="pick ? pick.title : mode === 'ai' ? 'Play a campaign' : 'Run a campaign'" @back="back"><template v-if="!pick"><div class="chips"><button v-for="b in BANDS" :key="b[0]" class="chip" :class="{ on: band === b[0] }" @click="band = b[0]">{{ b[1] }}</button></div></template></Bar>
  <div v-if="!pick" class="body scroll"><div class="grid"><button v-for="b in shown" :key="b.id" class="card" :data-id="b.id" @click="take(b)"><Cover :b="b" /><span class="pitch">{{ b.pitch }}</span><span class="tg">{{ b.tags.join(', ') }}</span></button></div><footer class="own"><div><h2>Something of your own</h2><p>{{ mode === 'ai' ? 'Let the game make up a tale on a ready-made map, or on one forged from a seed.' : 'Start from a ready-made map, forge one from a seed, or open an empty field and build by hand.' }}</p></div><button class="btn big" @click="app.modalArg = mode; app.screen = 'new'">{{ mode === 'ai' ? 'Invent a tale' : 'Forge a world' }}</button></footer></div>
  <div v-else class="body scroll"><article class="spread"><aside><Cover :b="pick" big /><table class="t facts"><tbody><tr><th>Levels</th><td>{{ pick.lo }} to {{ pick.hi }}</td></tr><tr><th>Length</th><td>{{ pick.chapters.length }} sittings<template v-if="pick.hours">, about {{ Math.floor(pick.hours) }} hours for four players</template>. Alone, with automatic dice, it goes faster.</td></tr><tr><th>Inside</th><td>{{ pick.places.length }} places, {{ pick.people }} people to talk to, {{ pick.fights }} set fights, {{ pick.scenes }} scenes, {{ pick.endings }} endings, {{ num(pick.words) }} words</td></tr><tr><th>Mood</th><td>{{ pick.tags.join(', ') }}</td></tr></tbody></table></aside>
    <section class="txt"><p class="lead">{{ pick.pitch }}</p><p v-for="(a, i) in pick.about" :key="i" class="aloud" v-html="rich(a)" />
      <h2>The sittings</h2><ol class="sit"><li v-for="(c, i) in pick.chapters" :key="i"><b>{{ c.title }}</b><span>{{ c.at }}</span><i>level {{ c.lvl }}</i></li></ol>
      <h2>The places</h2><p class="pl">{{ pick.places.map(p => `${p.name} (${KIND[p.kind] ?? p.kind})`).join('. ') }}.</p></section>
    <section class="form"><h2>Who runs it?</h2><div class="two"><button :class="{ on: mode === 'ai' }" @click="mode = 'ai'"><b>The game</b><small>You play a hero. It tells the story, runs the creatures and calls the rolls.</small></button><button :class="{ on: mode === 'dm' }" @click="mode = 'dm'"><b>I do</b><small>You are unseen and see all. The whole campaign is in your dock as a script.</small></button></div>
      <template v-if="mode === 'ai'"><h2>Your hero</h2><div class="hl"><button v-for="h in mine.list" :key="h.id" :class="{ on: mine.chosen === h.id }" :disabled="h.dead" @click="choose(h.id)"><Portrait :hero="h" :size="64" frame="bust" /><span><b class="cut">{{ h.name }}</b><small>Level {{ h.level }} {{ h.over?.race ?? sheet(h).race.name }} {{ h.over?.cls ?? sheet(h).cls.name.toLowerCase() }}{{ h.dead ? ', fallen' : '' }}</small></span></button><button class="new" @click="newHero"><b>Make or bring a hero</b><small>Create one here, or fill in a sheet you already have.</small></button></div><p v-if="hero && hero.level < pick.lo" class="note">{{ hero.name }} will be raised to level {{ pick.lo }}.</p><p v-else-if="hero && hero.level > pick.hi" class="note">{{ hero.name }} is level {{ hero.level }}. The fights will grow to match.</p></template>
      <h2>How hard?</h2><div class="chips"><button v-for="d in D" :key="d[0]" class="chip" :class="{ on: set.difficulty === d[0] }" @click="set.difficulty = d[0]">{{ d[1] }}</button></div>
      <button class="more" @click="more = !more">{{ more ? 'Fewer choices' : 'More choices' }}</button><div v-if="more" class="mo"><button class="opt" :class="{ on: set.handDice }" @click="set.handDice = !set.handDice"><i class="tick" /><span>Players may throw real dice and type the result</span></button><button class="opt" :class="{ on: set.ownSheets }" @click="set.ownSheets = !set.ownSheets"><i class="tick" /><span>Players may bring and amend their own sheets</span></button><button class="opt" :class="{ on: set.deathRule === 'heroic' }" @click="set.deathRule = set.deathRule === 'heroic' ? 'saves' : 'heroic'"><i class="tick" /><span>Heroes who fall only sleep until the fight ends</span></button><label class="lab">Throw for a player who is slow</label><div class="chips"><button v-for="s in [0, 45, 90, 180]" :key="s" class="chip s" :class="{ on: set.rollSecs === s }" @click="set.rollSecs = s">{{ s ? `after ${s} seconds` : 'never' }}</button></div><template v-if="mode === 'ai'"><label class="lab">A language model for free conversation (optional). The story itself needs none. Now: {{ llm.name }}</label><LlmForm /></template></div>
      <button class="btn primary big wide" :disabled="busy" @click="go">{{ mode === 'ai' ? 'Begin' : 'Open the box' }}</button></section></article></div></main></template>
<style scoped>
.sh{position:fixed;inset:0;display:flex;flex-direction:column}.body{flex:1;min-height:0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,218px),1fr));gap:34px 26px;padding:28px clamp(18px,3.2vw,48px) 20px;max-width:1560px;margin:0 auto}.card{display:flex;flex-direction:column;gap:0}.card :deep(.cv){transition:transform .12s}.card:hover :deep(.cv),.card:focus-visible :deep(.cv){transform:translateY(-7px)}.pitch{font-size:17px;line-height:1.28;margin-top:11px}.tg{font-size:14.5px;color:var(--ink3);margin-top:5px}
.own{display:flex;align-items:center;justify-content:space-between;gap:16px 40px;flex-wrap:wrap;border-top:5px solid var(--ink);margin:16px auto 0;max-width:1560px;padding:20px clamp(18px,3.2vw,48px) 40px}.own p{margin:5px 0 0;max-width:60ch}.own .btn{border:0;background:var(--ink);color:var(--paper)}
.spread{display:grid;grid-template-columns:minmax(240px,330px) minmax(0,1fr) minmax(300px,400px);gap:20px clamp(24px,3vw,52px);padding:28px clamp(18px,3.2vw,48px) 50px;max-width:1620px;margin:0 auto;align-items:start}.facts{margin-top:18px}.facts th{vertical-align:top;border-bottom:1px solid var(--line);padding:6px 14px 6px 0;white-space:nowrap;color:var(--ink);font-size:15px}.facts td{font-size:15.5px;line-height:1.3}.facts tr:last-child th{border-bottom:0}
.lead{font:700 clamp(27px,2.5vw,38px)/1.05 var(--serif);margin:0 0 18px;text-wrap:balance}.txt h2,.form h2{margin:26px 0 10px;border-bottom:3px solid var(--ink);padding-bottom:6px}.form h2:first-child{margin-top:0}.sit{list-style:none;padding:0;margin:0;counter-reset:s}.sit li{display:grid;grid-template-columns:34px 1fr auto;gap:0 10px;padding:7px 0;border-bottom:1px solid var(--line);align-items:baseline}.sit li::before{counter-increment:s;content:counter(s);font:800 25px/1 var(--serif)}.sit b{font:700 21px/1.05 var(--serif)}.sit span{grid-column:2;font-size:15px;color:var(--ink2)}.sit i{font-style:normal;font-size:15px;color:var(--ink2);grid-row:1;grid-column:3}.pl{font-size:16px}
.two{display:grid;grid-template-columns:1fr 1fr;gap:0;border:2px solid var(--ink)}.two button{padding:11px 13px 13px}.two button+button{border-left:2px solid var(--ink)}.two b,.hl b{display:block;font:700 21px/1.1 var(--serif)}.two small,.hl small{display:block;font-size:15px;line-height:1.25;color:var(--ink2);margin-top:3px}.two .on{background:var(--ink);color:var(--paper)}.two .on small{color:#c9ced4}
.hl{display:grid;gap:0;border:2px solid var(--ink);max-height:300px;overflow:auto}.hl button{display:flex;gap:12px;align-items:center;min-height:64px;border-bottom:1px solid var(--line)}.hl button>span:not(.pt){min-width:0;flex:1}.hl .new{display:block;padding:9px 13px 11px;border:0}.hl button:hover{background:var(--paper2)}.hl .on{background:var(--spot)!important;color:var(--on-spot)}.hl .on small{color:inherit}.hl button:disabled{opacity:.45}.note{font-size:15px;margin:8px 0 0}.more{margin:14px 0 4px;font-weight:500;text-decoration:underline;text-underline-offset:4px}.mo{padding:6px 0 10px}.form .big{margin-top:18px}
@media(max-width:1180px){.spread{grid-template-columns:minmax(220px,300px) 1fr}.form{grid-column:1/-1;max-width:640px}}@media(max-width:700px){.spread{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr;gap:24px 14px}.pitch{font-size:15.5px}.tg{display:none}aside :deep(.cv){max-width:300px}}
</style>
